fn voice(name: &str, lang: &str, local: bool, default: bool) -> Value {
  json!({
    "name": name,
    "lang": lang,
    "localService": local,
    "default": default,
    "voiceURI": name,
  })
}

struct Screen {
  width: u32,
  height: u32,
  dpr: f64,
  taskbar: u32,
}

struct Gpu {
  vendor: &'static str,
  renderer: &'static str,
}

