#[cfg(test)]
mod tests {
  use super::*;
  use crate::geolocation::{Geolocation, Locale};

  fn location() -> Geolocation {
    Geolocation {
      locale: Locale {
        language: "en".into(),
        region: Some("US".into()),
      },
      longitude: -122.6765,
      latitude: 45.5231,
      timezone: "America/Los_Angeles".into(),
    }
  }

  fn device(seed: &str, os: &str, location: Option<&Geolocation>) -> Value {
    generate(seed, os, "155.0.8059.79", location)
  }

  #[test]
  fn the_same_seed_always_presents_the_same_device() {
    assert_eq!(
      device("profile-a", "macos", None),
      device("profile-a", "macos", None)
    );
    assert_ne!(
      device("profile-a", "macos", None),
      device("profile-b", "macos", None)
    );
  }

  #[test]
  fn each_desktop_os_gets_a_matching_platform_and_user_agent() {
    let windows = device("seed", "windows", None);
    assert_eq!(windows["platform"], json!("Win32"));
    assert!(windows["userAgent"]
      .as_str()
      .unwrap()
      .contains("Windows NT 10.0"));

    let macos = device("seed", "macos", None);
    assert_eq!(macos["platform"], json!("MacIntel"));
    assert!(macos["userAgent"].as_str().unwrap().contains("Macintosh"));

    let linux = device("seed", "linux", None);
    assert_eq!(linux["platform"], json!("Linux x86_64"));
    assert!(linux["userAgent"].as_str().unwrap().contains("X11; Linux"));
  }

  #[test]
  fn the_exit_location_is_what_the_device_claims() {
    let location = location();
    let device = device("seed", "macos", Some(&location));
    assert_eq!(device["timezone"], json!("America/Los_Angeles"));
    assert_eq!(device["language"], json!("en-US"));
    assert_eq!(device["languages"], json!(["en-US", "en"]));
    assert_eq!(device["latitude"], json!(45.5231));
    assert_eq!(device["longitude"], json!(-122.6765));
    assert_eq!(device["timezoneOffset"], json!(480));
  }

  #[test]
  fn a_device_without_a_location_carries_no_location_fields() {
    let device = device("seed", "windows", None);
    for key in [
      "timezone",
      "timezoneOffset",
      "language",
      "languages",
      "latitude",
      "longitude",
      "accuracy",
    ] {
      assert!(device.get(key).is_none(), "{key} must stay unset");
    }
  }

  #[test]
  fn the_window_fits_the_screen_it_claims() {
    let device = device("seed", "linux", None);
    let read = |key: &str| device[key].as_u64().unwrap();
    assert!(read("windowInnerHeight") < read("windowOuterHeight"));
    assert!(read("windowOuterHeight") <= read("screenAvailHeight"));
    assert!(read("screenAvailHeight") <= read("screenHeight"));
    assert_eq!(read("windowOuterWidth"), read("screenWidth"));
  }

  #[test]
  fn the_payload_carries_the_fields_the_editor_expects() {
    let device = device("seed", "macos", Some(&location()));
    for key in [
      "userAgent",
      "platform",
      "hardwareConcurrency",
      "screenWidth",
      "windowOuterWidth",
      "webglVendor",
      "webglRenderer",
      "webglParameters",
      "fonts",
      "voices",
      "canvasNoiseSeed",
      "audioSampleRate",
      "batteryLevel",
      "vendor",
      "productSub",
    ] {
      assert!(device.get(key).is_some(), "{key} is missing");
    }
    assert!(device["webglParameters"].as_str().unwrap().len() > 20);
  }
}
